import unittest

from solution import merge_settings


class MergeSettingsTests(unittest.TestCase):
    def test_recursive_merge_and_replacement(self):
        base = {
            "service": {"host": "old", "ports": [80], "nested": {"a": 1}},
            "keep": True,
            "replace": {"old": 1},
        }
        overlay = {
            "service": {"host": "new", "nested": {"b": 2}},
            "replace": ["new"],
            "added": {"x": 3},
        }
        self.assertEqual(merge_settings(base, overlay), {
            "service": {"host": "new", "ports": [80], "nested": {"a": 1, "b": 2}},
            "keep": True,
            "replace": ["new"],
            "added": {"x": 3},
        })

    def test_key_insertion_order_at_each_level(self):
        base = {"b": 1, "a": {"x": 1, "y": 2}, "c": 3}
        overlay = {"a": {"y": 9, "z": 10}, "d": 4, "b": 8}
        result = merge_settings(base, overlay)
        self.assertEqual(list(result), ["b", "a", "c", "d"])
        self.assertEqual(list(result["a"]), ["x", "y", "z"])
        self.assertEqual(result["b"], 8)

    def test_empty_dictionaries(self):
        self.assertEqual(merge_settings({}, {}), {})
        self.assertEqual(merge_settings({"x": {}}, {"x": {}}), {"x": {}})
        self.assertEqual(merge_settings({}, {"x": 1}), {"x": 1})
        self.assertEqual(merge_settings({"x": 1}, {}), {"x": 1})

    def test_arbitrary_hashable_keys(self):
        key = ("tuple", 1)
        result = merge_settings({key: {1: "one"}, None: "base"}, {key: {2: "two"}, 7: "new"})
        self.assertEqual(result, {key: {1: "one", 2: "two"}, None: "base", 7: "new"})

    def test_type_validation(self):
        for base, overlay in (([], {}), ({}, []), (None, {}), ({}, None)):
            with self.subTest(base=base, overlay=overlay):
                with self.assertRaises(TypeError):
                    merge_settings(base, overlay)

    def test_result_does_not_alias_either_input(self):
        base = {"base_only": [{"x": 1}], "both": {"left": [1]}}
        overlay = {"overlay_only": [{"y": 2}], "both": {"right": [2]}}
        result = merge_settings(base, overlay)

        result["base_only"][0]["x"] = 100
        result["overlay_only"][0]["y"] = 200
        result["both"]["left"].append(9)
        result["both"]["right"].append(9)
        self.assertEqual(base, {"base_only": [{"x": 1}], "both": {"left": [1]}})
        self.assertEqual(overlay, {"overlay_only": [{"y": 2}], "both": {"right": [2]}})

        base["base_only"][0]["x"] = -1
        overlay["overlay_only"][0]["y"] = -2
        self.assertEqual(result["base_only"][0]["x"], 100)
        self.assertEqual(result["overlay_only"][0]["y"], 200)


if __name__ == "__main__":
    unittest.main()

